CREATE USER IF NOT EXISTS "SA" PASSWORD '' ADMIN;              
CREATE CACHED TABLE "public"."veiculos"(
    "id_veiculo" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 6) DEFAULT ON NULL NOT NULL,
    "codigo_frota" CHARACTER VARYING(40) NOT NULL,
    "categoria" CHARACTER VARYING(30) NOT NULL,
    "max_passageiros" INTEGER NOT NULL,
    "volume_maximo_m3" DECIMAL(12, 3) NOT NULL,
    "ar_condicionado" BOOLEAN NOT NULL,
    "consumo_medio_km_l" DECIMAL(12, 3) NOT NULL,
    "potencia_cv" DECIMAL(12, 3) NOT NULL,
    "valor_diaria" DECIMAL(12, 2) NOT NULL,
    "ativo" BOOLEAN NOT NULL
);           
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7" PRIMARY KEY("id_veiculo");              
