CREATE CACHED TABLE "public"."locacoes"(
    "id_locacao" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 7) DEFAULT ON NULL NOT NULL,
    "id_cliente" BIGINT NOT NULL,
    "id_veiculo" BIGINT NOT NULL,
    "data_retirada" DATE NOT NULL,
    "data_devolucao" DATE NOT NULL,
    "local_retirada" CHARACTER VARYING(160) NOT NULL,
    "local_devolucao" CHARACTER VARYING(160) NOT NULL,
    "gps_selecionado" BOOLEAN NOT NULL,
    "seguro_selecionado" BOOLEAN NOT NULL,
    "diaria_veiculo_aplicada" DECIMAL(12, 2) NOT NULL,
    "diaria_gps_aplicada" DECIMAL(12, 2) NOT NULL,
    "diaria_seguro_aplicada" DECIMAL(12, 2) NOT NULL,
    "status" CHARACTER VARYING(20) DEFAULT 'CONFIRMADA' NOT NULL,
    "categoria_aplicada" CHARACTER VARYING(30),
    "retirada_real_em" DATE,
    "devolucao_real_em" DATE,
    "cancelada_em" TIMESTAMP,
    "motivo_cancelamento" CHARACTER VARYING(500),
    "origem_migracao" BOOLEAN DEFAULT FALSE NOT NULL,
    "historico" BOOLEAN DEFAULT FALSE NOT NULL,
    "devolucao_registrada_em" TIMESTAMP,
    "multa_atraso" DECIMAL(19, 2)
);           
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_71" PRIMARY KEY("id_locacao");             
