ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_7147F" CHECK("data_devolucao" >= "data_retirada") NOCHECK; 
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_7147FAB" CHECK("diaria_gps_aplicada" >= CAST(0 AS NUMERIC(1))) NOCHECK;    
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7976D" CHECK("consumo_medio_km_l" >= CAST(0 AS NUMERIC(1))) NOCHECK;       
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_797" CHECK("max_passageiros" >= 0) NOCHECK;
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_7147FA" CHECK("diaria_veiculo_aplicada" > CAST(0 AS NUMERIC(1))) NOCHECK;  
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."ck_locacao_estado" CHECK(("categoria_aplicada" IN('PICKUP', 'VAN', 'CAMINHAO_MEDIO', 'CAMINHAO_GRANDE', 'TRAILER'))
    AND ("categoria_aplicada" IS NOT NULL)
    AND ((("status" = 'CONFIRMADA')
    AND ("retirada_real_em" IS NULL)
    AND ("devolucao_real_em" IS NULL)
    AND ("cancelada_em" IS NULL)
    AND ("motivo_cancelamento" IS NULL))
    OR (("status" = 'EM_USO')
    AND ("retirada_real_em" IS NOT NULL)
    AND ("devolucao_real_em" IS NULL)
    AND ("cancelada_em" IS NULL)
    AND ("motivo_cancelamento" IS NULL))
    OR (("status" = 'CANCELADA')
    AND ("retirada_real_em" IS NULL)
    AND ("devolucao_real_em" IS NULL)
    AND ("cancelada_em" IS NOT NULL)
    AND ("motivo_cancelamento" IS NOT NULL)
    AND (CHAR_LENGTH(TRIM("motivo_cancelamento")) > 0))
    OR (("status" = 'CONCLUIDA')
    AND ("retirada_real_em" IS NOT NULL)
    AND ("devolucao_real_em" IS NOT NULL)
    AND ("cancelada_em" IS NULL)
    AND ("motivo_cancelamento" IS NULL)
    AND ("devolucao_real_em" >= "retirada_real_em")))) NOCHECK;      
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7976D244" CHECK("categoria" IN('PICKUP', 'VAN', 'CAMINHAO_MEDIO', 'CAMINHAO_GRANDE', 'TRAILER')) NOCHECK;  
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7976D2" CHECK("potencia_cv" >= CAST(0 AS NUMERIC(1))) NOCHECK;             
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7976" CHECK("volume_maximo_m3" >= CAST(0 AS NUMERIC(1))) NOCHECK;          
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_7147FABB" CHECK("diaria_seguro_aplicada" >= CAST(0 AS NUMERIC(1))) NOCHECK;
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_7976D24" CHECK("valor_diaria" > CAST(0 AS NUMERIC(1))) NOCHECK;            
ALTER TABLE "public"."clientes" ADD CONSTRAINT "public"."CONSTRAINT_36" UNIQUE NULLS DISTINCT ("documento");   
ALTER TABLE "public"."veiculos" ADD CONSTRAINT "public"."CONSTRAINT_79" UNIQUE NULLS DISTINCT ("codigo_frota");
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_7147" FOREIGN KEY("id_veiculo") REFERENCES "public"."veiculos"("id_veiculo") NOCHECK;      
ALTER TABLE "public"."locacoes" ADD CONSTRAINT "public"."CONSTRAINT_714" FOREIGN KEY("id_cliente") REFERENCES "public"."clientes"("id_cliente") NOCHECK;       
